UPDATE channel_transaction
SET reserved_refund_cents=reserved_refund_cents+#{amountCents}
WHERE payment_no=#{paymentNo}
  AND status='SUCCEEDED'
  AND #{amountCents}>0
  AND #{amountCents}<=amount_cents-reserved_refund_cents-succeeded_refund_cents

UPDATE channel_transaction
SET reserved_refund_cents=reserved_refund_cents-#{amountCents},succeeded_refund_cents=succeeded_refund_cents+#{succeededRefundCents}
WHERE payment_no=#{paymentNo}
  AND reserved_refund_cents>=#{amountCents}
